429	    pub(crate) fn attach_tp_comm(&mut self, comm: Comm) {
430	        self.tp_comm = Some(comm);
431	    }
432	
433	    /// Force NCCL connect before any CUDA Graph capture records a collective
434	    /// (lazy connect inside `cuStreamBeginCapture` wedges the capture). NCCL
435	    /// 2.22+ connects per size-selected algorithm, so warm one all-reduce at
436	    /// every decode bucket's message size. No-op without a TP communicator.
437	    pub(crate) fn warmup_tp_collective(&self) -> Result<()> {
438	        if let Some(comm) = &self.tp_comm {
439	            let buckets = super::batch_decode_graph::BATCH_BUCKETS;
440	            let max_elems = buckets.last().unwrap() * self.config.hidden_size;
441	            let mut scratch = self
442	                .ctx
443	                .stream
444	                .alloc_zeros::<half::bf16>(max_elems)
445	                .map_err(|e| anyhow::anyhow!("alloc NCCL warm-up scratch: {e}"))?;
446	            for &bucket in buckets {
447	                let mut view = scratch.slice_mut(0..bucket * self.config.hidden_size);
448	                comm.all_reduce_in_place(&mut view, &ReduceOp::Sum)
449	                    .map_err(|e| {
450	                        anyhow::anyhow!("Qwen3.5 NCCL warm-up all-reduce failed: {e:?}")
451	                    })?;
452	            }
453	            self.ctx
454	                .stream
455	                .synchronize()
456	                .map_err(|e| anyhow::anyhow!("Qwen3.5 NCCL warm-up sync failed: {e}"))?;
457	        }
458	        Ok(())
459	    }
460	
461	    pub(crate) fn all_reduce_hidden(&self, hidden: &mut HiddenStates) -> Result<()> {
462	        self.all_reduce_hidden_untraced(hidden)
463	    }
464	
465	    fn all_reduce_hidden_untraced(&self, hidden: &mut HiddenStates) -> Result<()> {
466	        if let Some(comm) = &self.tp_comm {
467	            comm.all_reduce_in_place(&mut hidden.data, &ReduceOp::Sum)
468	                .map_err(|e| anyhow::anyhow!("Qwen3.5 NCCL all-reduce failed: {e:?}"))?;
469	        }
470	        Ok(())
471	    }
472	
473	    /// Tune small-batch decode GEMM algorithms on the thread that will capture
474	    /// or replay the CUDA Graph. cuBLASLt plans are thread-local, so scheduler
475	    /// workers and model-local executors must call this after binding CUDA.
476	    /// Repeated calls on the same thread return from the existing plan cache;
477	    /// calls on different worker threads populate separate thread-local plans.
478	    pub(crate) fn tune_decode_gemm_algos(&self) -> Result<()> {
479	        let ctx = &self.ctx;
480	        let hidden = self.config.hidden_size;
481	        let vocab = self.config.selection_vocab;
482	        let geom = self.geometry;
483	        let full_q = geom.local_full_attn_gated_q_dim();
484	        let full_kv = geom.local_full_attn_kv_dim();
485	        let linear_qkv = geom.local_linear_qkv_dim();
486	        let linear_z = geom.local_linear_z_dim();
487	        let linear_ba = geom.local_linear_num_value_heads();
488	        let intermediate = geom.local_intermediate_size();
489	
490	        let full_attn = || {
491	            self.layers
492	                .iter()
493	                .filter_map(|layer| layer.attn.full_attention())
494	        };
495	        let linear_attn = || {
496	            self.layers
497	                .iter()
498	                .filter_map(|layer| layer.attn.linear_attention())
499	        };
500	        let full_q_samples = sample_mats(full_attn().map(|attn| &attn.q_proj));
501	        let full_kv_samples =
502	            sample_mats(full_attn().flat_map(|attn| [&attn.k_proj, &attn.v_proj]));
503	        let full_o_samples = sample_mats(full_attn().map(|attn| &attn.o_proj));
504	        let linear_qkvz_samples = sample_mats(linear_attn().map(|attn| &attn.in_proj_qkvz));
505	        let linear_ba_samples = sample_mats(linear_attn().map(|attn| &attn.in_proj_ba));
506	        let linear_out_samples = sample_mats(linear_attn().map(|attn| &attn.out_proj));
507	        let gate_up_samples = sample_mats(self.layers.iter().map(|layer| &layer.mlp.gate_up_proj));
508	        let down_samples = sample_mats(self.layers.iter().map(|layer| &layer.mlp.down_proj));
509	        let lm_head_samples = sample_mats([self.output_projection()]);
510	
511	        for &n in super::batch_decode_graph::BATCH_BUCKETS
512	            .iter()
513	            .filter(|&&bucket| {
514	                // Keep in sync with MAX_SHARED_SM_DECODE_BATCH: buckets above
515	                // GEMM_LT_MAX_N do not have an independent tuned decode GEMM
516	                // route today, so Shared-SM overlap rejects them at startup.
517	                bucket <= crate::ops::GEMM_LT_MAX_N && bucket <= self.reserved_decode_slots
518	            })
519	        {
520	            tune_if_nonempty(ctx, &full_q_samples, full_q, n)?;
521	            tune_if_nonempty(ctx, &full_kv_samples, full_kv, n)?;
522	            tune_if_nonempty(ctx, &full_o_samples, hidden, n)?;
523	            tune_if_nonempty(ctx, &linear_qkvz_samples, linear_qkv + linear_z, n)?;
524	            tune_if_nonempty(ctx, &linear_ba_samples, 2 * linear_ba, n)?;
525	            tune_if_nonempty(ctx, &linear_out_samples, hidden, n)?;
526	            crate::ops::gemm_lt_tune(ctx, &gate_up_samples, 2 * intermediate, n)?;
527	            crate::ops::gemm_lt_tune(ctx, &down_samples, hidden, n)?;
528	            crate::ops::gemm_lt_tune(ctx, &lm_head_samples, vocab, n)?;
529	        }
530	        Ok(())
531	    }
532	
533	    /// Create the CUDA Graph batch decode state at the loaded capacity.
534	    pub(crate) fn create_batch_decode_graph_state(
535	        &self,
536	        padding_page_id: i32,
537	    ) -> anyhow::Result<super::batch_decode_graph::BatchDecodeGraphState> {
538	        self.create_batch_decode_graph_state_with_capacity(
539	            self.reserved_decode_slots,
540	            padding_page_id,
541	        )
542	    }
543	
544	    pub(crate) fn create_batch_decode_graph_state_with_capacity(
545	        &self,
546	        max_batch: usize,
547	        padding_page_id: i32,
548	    ) -> anyhow::Result<super::batch_decode_graph::BatchDecodeGraphState> {
549	        anyhow::ensure!(
550	            max_batch <= self.reserved_decode_slots,
551	            "requested graph capacity {max_batch} exceeds loaded capacity {}",
552	            self.reserved_decode_slots
553	        );
554	        super::batch_decode_graph::BatchDecodeGraphState::with_capacity(
555	            &self.ctx,
556	            &self.config,
557	            self.geometry,
558	            self.kv_buffer.layout().page_size,
559	            padding_page_id,
560	            max_batch,
561	        )
562	    }
563	
564	    pub(crate) fn create_batch_decode_buffers_with_capacity(
565	        &self,
566	        max_batch: usize,
567	        padding_page_id: i32,
568	    ) -> anyhow::Result<super::decode_buffers::BatchDecodeBuffers35> {
569	        super::decode_buffers::BatchDecodeBuffers35::new(
570	            &self.ctx,
571	            &self.config,
572	            self.geometry,
573	            max_batch,
574	            self.kv_buffer.layout().page_size,
575	            padding_page_id,
576	        )
577	    }
578	
579	    pub(crate) fn is_stop_token(&self, token_id: u32) -> bool {
580	        self.config.eos_token_ids.contains(&token_id)
581	    }
582	}
583	
584	/// Wrap the matrices one tuning pass samples into cuBLASLt tune candidates.
585	fn sample_mats<'a>(
586	    mats: impl IntoIterator<Item = &'a DeviceMatrix>,
587	) -> Vec<(&'a DeviceMatrix, usize)> {
588	    mats.into_iter().map(|m| (m, 0)).collect()
589	}
