79	/// MLP layer weights (shared between both layer types).
80	#[allow(clippy::struct_field_names)]
81	pub(crate) struct MLP35 {
82	    pub(crate) gate_up_proj: DeviceMatrix,
83	    pub(crate) down_proj: DeviceMatrix,
84	}
85	
86	impl MLP35 {
87	    fn load(src: &WeightSource, prefix: &str) -> Result<Self> {
88	        let gate_proj =
89	            src.row_shard_if_needed(&format!("{prefix}.mlp.gate_proj.weight"), src.intermediate)?;
90	        let up_proj =
91	            src.row_shard_if_needed(&format!("{prefix}.mlp.up_proj.weight"), src.intermediate)?;
92	        let gate_up_proj = DeviceMatrix::vstack(src.ctx, &[&gate_proj, &up_proj])?;
93	        drop(gate_proj);
94	        drop(up_proj);
95	        Ok(Self {
96	            gate_up_proj,
97	            down_proj: src
98	                .col_shard_if_needed(&format!("{prefix}.mlp.down_proj.weight"), src.intermediate)?,
99	        })
100	    }
101	}
