135	impl FullAttentionLayer {
136	    fn load(src: &WeightSource, prefix: &str) -> Result<Self> {
137	        Ok(Self {
138	            q_proj: src.gated_q_proj(&format!("{prefix}.q_proj.weight"))?,
139	            k_proj: src.row_shard_if_needed(&format!("{prefix}.k_proj.weight"), src.kv_rows)?,
140	            v_proj: src.row_shard_if_needed(&format!("{prefix}.v_proj.weight"), src.kv_rows)?,
141	            o_proj: src.col_shard_if_needed(&format!("{prefix}.o_proj.weight"), src.q_cols)?,
142	            q_norm: src.tensor_1d(&format!("{prefix}.q_norm.weight"))?,
143	            k_norm: src.tensor_1d(&format!("{prefix}.k_norm.weight"))?,
144	        })
